		} else if (!triNode->kids[0]) {
			// Reached triangle leaf node, recursively descend through edge nodes
			stack[++stackpos] = stackobj { edgeNode->kids[1], curr.triNode };
			stack[++stackpos] = stackobj { edgeNode->kids[0], curr.triNode };
